const units = { 'L': 'L', 'un': 'pcs', 'conj.': 'sets', 'par': 'pair', 'hábito': 'habit', 'dias': 'days' };
const u = x => units[x] ?? x;
const whenEn = s => s.replace(/^hoje/, 'today').replace(/^amanhã/, 'tomorrow').replace(/^ontem/, 'yesterday').replace(' às ', ' at ');
const sms = (n, loc) => `SMS to ${n} person${n === '1' ? '' : 's'}${loc ? ', with your location' : ''}.`;

// Regras para frases com números ou nomes. A primeira que encaixar é usada.
export const EN_RULES = [
  [/^· para (\d+) pessoa\(s\) ·$/, (_, n) => `· for ${n} ${n === '1' ? 'person' : 'people'} ·`],
  [/^(.+) \(eu\)$/, '$1 (me)'],
  [/^Próximo: (.+) · (\d+) de (\d+) feitos$/, (_, a, b, c) => `Next: ${trIn(a)} · ${b} of ${c} done`],
  [/^O seu plano · (\d+) de (\d+)$/, 'Your plan · $1 of $2'],
  [/^(\d+) pessoa\(s\)$/, (_, n) => `${n} ${n === '1' ? 'person' : 'people'}`],
  [/^(\d+) pessoa\(s\) em casa$/, (_, n) => `${n} ${n === '1' ? 'person' : 'people'} at home`],
  [/^(\d+) de (\d+) combinados$/, '$1 of $2 agreed'],
  [/^(.+): (\d+) de (\d+) essenciais$/, (_, k, a, b) => `${trIn(k)}: ${a} of ${b} essentials`],
  [/^Essenciais: (\d+) de (\d+)$/, 'Essentials: $1 of $2'],
  [/^Atualizado (.+)$/, 'Updated $1'],
  [/^(\d+) mensagens por ler$/, '$1 unread messages'],
  [/^há (\d+) min$/, '$1 min ago'], [/^há (\d+) h$/, '$1 h ago'], [/^agora$/, 'just now'],
  [/^· (.+)$/, (_, a) => `· ${trIn(a)}`],
  [/^antirrábica até (.+)$/, 'rabies vaccine until $1'],
  [/^(\d+) pontos, disponíveis offline\.(.*)$/, '$1 points, available offline.$2'],
  [/^Última atualização: (.+)$/, 'Last update: $1'],
  [/^Fonte: OpenStreetMap \((.+)\)\. Confirme os números no site da sua câmara\.$/, 'Source: OpenStreetMap ($1). Check the numbers on your council’s website.'],
  [/^Ligar (?:a|para) (.+)$/, (_, a) => `Call ${trIn(a)}`],
  [/^Rádio · Antena 1 \((.+)\)$/, 'Radio · Antena 1 ($1)'],
  [/^Rádio Antena 1 \((.+)\):$/, 'Antena 1 radio ($1):'],
  [/^Os dados ficam neste telemóvel\. Última cópia: (.+)\.$/, 'Your data stays on this phone. Last backup: $1.'],
  [/^Subir (.+)$/, (_, a) => `Move up ${trIn(a)}`], [/^Descer (.+)$/, (_, a) => `Move down ${trIn(a)}`],
  [/^O que combinámos · (\d+) de (\d+)$/, 'What we agreed · $1 of $2'],
  [/^Ponto de encontro e contactos da família · atualizado em (.+)$/, 'Family meeting point and contacts · updated $1'],
  [/^(Medicação|Alergias|Necessidades): (.+)$/, (_, k, v) => `${{ Medicação: 'Medication', Alergias: 'Allergies', Necessidades: 'Needs' }[k]}: ${v}`],
  [/^SMS para (\d+) pessoa\(s\), com a sua localização\.$/, (_, n) => sms(n, true)],
  [/^SMS para (\d+) pessoa\(s\)\.$/, (_, n) => sms(n, false)],
  [/^(\d+) passos$/, '$1 steps'], [/^Passo (\d+) de (\d+)$/, 'Step $1 of $2'],
  [/^Só o que falta(?: \((\d+)\))?$/, (_, n) => `Only what’s missing${n ? ` (${n})` : ''}`],
  [/^Falta para ([\d,]+) dias$/, 'Needed for $1 days'],
  [/^Falta ([\d,]+) de ([\d,]+) (.+)$/, (_, a, b, x) => `Missing ${a} of ${b} ${u(x)}`],
  [/^Falta ([\d,]+) (.+)$/, (_, a, x) => `Missing ${a} ${u(x)}`],
  [/^(\d+) em falta$/, '$1 missing'],
  [/^Marcar que tenho: (.+)$/, (_, a) => `Mark as owned: ${trIn(a)}`], [/^Já tenho: (.+)$/, (_, a) => `Already have: ${trIn(a)}`],
  [/^Ponto de encontro: (.+)$/, 'Meeting point: $1'],
  [/^Nome da pessoa (\d+)$/, 'Name of person $1'], [/^Telemóvel da pessoa (\d+)$/, 'Mobile of person $1'],
  [/^Grupo: (.+)$/, (_, a) => `Group: ${trIn(a)}`],
  [/^Mais (\d+) avisos?$/, (_, n) => `${n} more alert${n === '1' ? '' : 's'}`],
  [/^\+(\d+) aviso\(s\)$/, '+$1 alert(s)'],
  [/^(\d+) a expirar · ver$/, '$1 expiring · see'], [/^(\d+) expirado\(s\)$/, '$1 expired'], [/^(\d+) a expirar$/, '$1 expiring'],
  [/^Expira em (\d+) dias?$/, (_, n) => `Expires in ${n} day${n === '1' ? '' : 's'}`], [/^Expirado \((.+)\)$/, 'Expired ($1)'], [/^Válido até (.+)$/, 'Valid until $1'],
  [/^Ativo até (.+)$/, (_, a) => `Active until ${whenEn(a)}`],
  [/^De (.+) até (.+)$/, (_, a, b) => `From ${whenEn(a)} to ${whenEn(b)}`],
  [/^Aviso (amarelo|laranja|vermelho)$/, (_, c) => `${{ amarelo: 'Yellow', laranja: 'Orange', vermelho: 'Red' }[c]} warning`],
  [/^Risco de incêndio (.+) hoje$/, (_, a) => `${trIn(a[0].toUpperCase() + a.slice(1))} fire risk today`],
  [/^Risco de incêndio (.+)$/, (_, a) => `${trIn(a[0].toUpperCase() + a.slice(1))} fire risk`],
  [/^Sismo de magnitude (.+)$/, 'Magnitude $1 earthquake'], [/^Magnitude (.+)$/, 'Magnitude $1'],
  [/^a ([\d,]+ k?m)( de si)?$/, (_, d, s2) => `${d}${s2 ? ' from you' : ' away'}`],
  [/^Sem sismos nos últimos 7 dias( perto de si)?\.$/, (_, p) => `No earthquakes in the last 7 days${p ? ' near you' : ''}.`],
  [/^Avisos para (.+) \(pela sua localização\)\.$/, 'Alerts for $1 (from your location).'],
  [/^Agora · (.+)$/, 'Now · $1'],
  [/^Copiado: (.+)$/, 'Copied: $1'],
  [/^(.+): essenciais prontos\.$/, (_, a) => `${trIn(a)}: essentials ready.`],
  [/^Adicionado a "(.+)"\.$/, 'Added to "$1".'], [/^Entrou no grupo "(.+)"\.$/, 'Joined the group "$1".'], [/^Grupo "(.+)" atualizado\.$/, 'Group "$1" updated.'],
  [/^(\d+) pontos de Lisboa atualizados\.$/, '$1 Lisbon points updated.'],
  [/^Mensagens · (.+)$/, (_, a) => `Messages · ${trIn(a)}`],
  [/^(.+) · assuntos não urgentes$/, (_, a) => `${trIn(a)} · non-urgent matters`],
  [/^Feito em (.+)$/, 'Done on $1'], [/^Guardado em (.+)$/, 'Saved on $1'],
  [/^Zona guardada em (.+) \((\d+) partes\)\.$/, 'Area saved on $1 ($2 tiles).'], [/^A guardar… (\d+) de (\d+)$/, 'Saving… $1 of $2'],
  [/^Mapa guardado \((\d+) partes\)\. Funciona sem internet\.$/, 'Map saved ($1 tiles). Works offline.'],
  [/^Bloquear "(.+)" \(#(\w+)\)\? Deixa de ver as mensagens deste dispositivo\.$/, 'Block "$1" (#$2)? You’ll stop seeing messages from this device.'],
  [/^Pronto para (.+)$/, 'Ready for $1'],
  [/^(\d+) remetente\(s\) bloqueado\(s\)\.$/, '$1 sender(s) blocked.'],
  [/^(\d+) pessoa\(s\) · (.+)$/, (_, n, rest) => `${n} ${n === '1' ? 'person' : 'people'} · ${rest}`],
  [/^Ponto oficial mais próximo · (.+) para (\w+)$/, 'Nearest official point · $1 to the $2'],
  [/^Câmara Municipal de (.+)$/, '$1 City Council'],
];
